[CmdletBinding()]
param([string]$Root='Assets',[string]$ProjectRoot='.',[int]$MaxFiles=256,[int]$MaxParallel=4,[string]$OutputPath='ES/Output/ResourceReader/unity-cache-batch.json')
$ErrorActionPreference='Stop'; $rootFull=(Resolve-Path -LiteralPath (Join-Path (Resolve-Path $ProjectRoot).Path $Root)).Path; $projectFull=(Resolve-Path -LiteralPath $ProjectRoot).Path
$extensions=@('.unity','.prefab','.asset','.mat','.controller','.anim','.shader','.compute'); $files=@(Get-ChildItem -LiteralPath $rootFull -File -Recurse | Where-Object {$extensions -contains $_.Extension.ToLowerInvariant() -and $_.Length -le 104857600} | Select-Object -First $MaxFiles)
$reader=Join-Path $projectFull '.agents/skills/es-resource-reader/scripts/Invoke-ESResourceReader.ps1'; $cache=Join-Path $projectFull '.agents/skills/es-task-read-snapshot/scripts/Invoke-ESProjectionCache.ps1'; $cacheRoot='ES/Output/FileProjectionCache'
$worker={param($file,$root,$readerPath,$cachePath,$cacheRootPath); try { $projectionText=& $readerPath -Path $file.FullName | Out-String; $projection=$projectionText|ConvertFrom-Json; if($projection.errors.Count -gt 0){throw [string]($projection.errors -join '; ')}; $relative=$file.FullName.Substring($root.Length).TrimStart('\','/').Replace('\','/'); $temp=[IO.Path]::Combine($root,'ES/Output/ResourceReader/.tmp/es-reader-projection-'+[Guid]::NewGuid().ToString('N')+'.json'); try { New-Item -ItemType Directory -Force -Path (Split-Path $temp)|Out-Null; [IO.File]::WriteAllText($temp,$projectionText,(New-Object Text.UTF8Encoding($false))); $tempRelative=$temp.Substring($root.Length).TrimStart('\','/').Replace('\','/'); $receipt=& $cachePath -Mode Write -ProjectRoot $root -SourcePath $relative -ParserId $projection.parserId -ParserVersion '1' -ProjectionPath $tempRelative -CacheRoot $cacheRootPath | Out-String; [pscustomobject]@{sourcePath=$relative;status='stored';parserId=$projection.parserId;objectCount=[int]$projection.summary.objectCount;dependencyEdgeCount=[int]$projection.summary.dependencyEdgeCount} } finally {if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}} } catch { [pscustomobject]@{sourcePath=$file.FullName;status='error';error=$_.Exception.Message} }}
$pool=[RunspaceFactory]::CreateRunspacePool(1,[Math]::Max(1,$MaxParallel));$pool.Open();$pending=[Collections.Generic.List[object]]::new();$results=[Collections.Generic.List[object]]::new();$sw=[Diagnostics.Stopwatch]::StartNew()
foreach($file in $files){$ps=[PowerShell]::Create();$ps.RunspacePool=$pool;[void]$ps.AddScript($worker).AddArgument($file).AddArgument($projectFull).AddArgument($reader).AddArgument($cache).AddArgument($cacheRoot);$pending.Add([pscustomobject]@{PS=$ps;Handle=$ps.BeginInvoke()})};foreach($job in $pending){try{$r=$job.PS.EndInvoke($job.Handle);foreach($x in $r){[void]$results.Add($x)}}finally{$job.PS.Dispose()}};$sw.Stop();$pool.Close();$pool.Dispose();$ordered=@($results|Sort-Object sourcePath);$out=[ordered]@{schemaVersion=1;batchId='es-resource-reader.unity-cache-batch.v1';root=$rootFull;fileCount=$files.Count;storedCount=@($ordered|Where-Object status -eq 'stored').Count;errorCount=@($ordered|Where-Object status -eq 'error').Count;maxParallel=$MaxParallel;elapsedMilliseconds=$sw.ElapsedMilliseconds;filesPerSecond=if($sw.Elapsed.TotalSeconds -gt 0){[Math]::Round($files.Count/$sw.Elapsed.TotalSeconds,2)}else{0};results=$ordered;nonClaims=@('Unity import','runtime behavior','release behavior')};$dest=Join-Path $projectFull $OutputPath;New-Item -ItemType Directory -Force -Path (Split-Path $dest)|Out-Null;$out|ConvertTo-Json -Depth 12|Set-Content -LiteralPath $dest -Encoding UTF8;$out|ConvertTo-Json -Depth 12
